index 582036922d05..c1eacd291e9e 100644
--- a/collection_of_linux_repos/linux-573/mm/mmap.c
+++ b/collection_of_linux_repos/linux-573/mm/mmap.c
@@ -1658,7 +1658,7 @@ SYSCALL_DEFINE5(remap_file_pages, unsigned long, start, unsigned long, size,
 	if (pgoff + (size >> PAGE_SHIFT) < pgoff)
 		return ret;

-	if (mmap_write_lock_killable(mm))
+	if (mmap_read_lock_killable(mm))
 		return -EINTR;

 	vma = vma_lookup(mm, start);
@@ -1701,20 +1701,37 @@ SYSCALL_DEFINE5(remap_file_pages, unsigned long, start, unsigned long, size,
 		flags |= MAP_LOCKED;

 	file = get_file(vma->vm_file);
-	ret = security_mmap_file(vma->vm_file, prot, flags);
-	if (ret)
-		goto out_fput;
-	ret = do_mmap(vma->vm_file, start, size,
+	mmap_read_unlock(mm);
+
+	ret = security_mmap_file(file, prot, flags);
+	if (ret) {
+		fput(file);
+		return ret;
+	}
+
+	ret = -EINTR;
+	if (mmap_write_lock_killable(mm)) {
+		fput(file);
+		return ret;
+	}
+
+	ret = do_mmap(file, start, size,
 			prot, flags, 0, pgoff, &populate, NULL);
-out_fput:
 	fput(file);
-out:
 	mmap_write_unlock(mm);
 	if (populate)
 		mm_populate(ret, populate);
 	if (!IS_ERR_VALUE(ret))
 		ret = 0;
 	return ret;
+
+out:
+	mmap_read_unlock(mm);
+	if (populate)
+		mm_populate(ret, populate);
+	if (!IS_ERR_VALUE(ret))
+		ret = 0;
+	return ret;
 }

