+struct folio *hugetlb_memfd_alloc_folio(struct hstate *h, struct file *file,
+					pgoff_t idx, gfp_t gfp_mask,
+					int nid, nodemask_t *nmask)
+{
+	struct inode *inode = file_inode(file);
+	struct resv_map *resv_map = inode_resv_map(inode);
+	struct hugepage_subpool *spool = subpool_inode(inode);
+	struct hugetlb_cgroup *h_cg = NULL;
+	struct folio *folio;
+	long chg, gbl_chg;
+	long regions_needed = 0;
+
+	folio = filemap_get_folio(file->f_mapping, idx << huge_page_order(h));
+	if (!IS_ERR(folio)) {
+		folio_unlock(folio);
+		folio_put(folio);
+		return ERR_PTR(-EEXIST);
+	}
+
+	/*
+	 * memfd_alloc_folio() may be called for a file with no reservation
+	 * (e.g. hole punching). In that case, we need to allocate a page
+	 * and consume a reservation if one exists, or allocate a surplus
+	 * page and add a reservation.
+	 */
+	chg = region_chg(resv_map, idx, idx + 1, &regions_needed);
+	if (chg < 0)
+		return ERR_PTR(chg);
+
+	if (chg) {
+		gbl_chg = hugepage_subpool_get_pages(spool, 1);
+		if (gbl_chg < 0) {
+			region_abort(resv_map, idx, idx + 1, regions_needed);
+			return ERR_PTR(-ENOSPC);
+		}
+
+		if (hugetlb_acct_memory(h, gbl_chg) < 0) {
+			if (gbl_chg)
+				hugepage_subpool_put_pages(spool, 1);
+			region_abort(resv_map, idx, idx + 1, regions_needed);
+			return ERR_PTR(-ENOMEM);
+		}
+
+		if (hugetlb_cgroup_charge_cgroup_rsvd(hstate_index(h),
+				pages_per_huge_page(h), &h_cg) < 0) {
+			if (gbl_chg) {
+				hugepage_subpool_put_pages(spool, 1);
+				hugetlb_acct_memory(h, -gbl_chg);
+			}
+			region_abort(resv_map, idx, idx + 1, regions_needed);
+			return ERR_PTR(-ENOMEM);
+		}
+	}
+
+	folio = alloc_hugetlb_folio_reserve(h, nid, nmask, gfp_mask);
+	if (!folio) {
+		if (chg) {
+			long rsv_adjust;
+
+			hugetlb_cgroup_uncharge_cgroup_rsvd(hstate_index(h),
+					pages_per_huge_page(h), h_cg);
+
+			rsv_adjust = hugepage_subpool_put_pages(spool, 1);
+			hugetlb_acct_memory(h, -rsv_adjust);
+		}
+		region_abort(resv_map, idx, idx + 1, regions_needed);
+		return ERR_PTR(-ENOMEM);
+	}
+
+	region_add(resv_map, idx, idx + 1, regions_needed, h, h_cg);
+	return folio;
+}
