--- a/collection_of_linux_repos/linux-575/drivers/net/tun.c
+++ b/collection_of_linux_repos/linux-575/drivers/net/tun.c
@@ -1661,6 +1661,7 @@ static struct sk_buff *tun_build_skb(struct tun_struct *tun,
 				     int len, int *skb_xdp)
 {
 	struct page_frag *alloc_frag = &current->task_frag;
+	struct bpf_net_context __bpf_net_ctx, *bpf_net_ctx;
 	struct bpf_prog *xdp_prog;
 	int buflen = SKB_DATA_ALIGN(sizeof(struct skb_shared_info));
 	char *buf;
@@ -1699,6 +1700,7 @@ static struct sk_buff *tun_build_skb(struct tun_struct *tun,
 	*skb_xdp = 0;

 	local_bh_disable();
+	bpf_net_ctx = bpf_net_ctx_set(&__bpf_net_ctx);
 	rcu_read_lock();
 	xdp_prog = rcu_dereference(tun->xdp_prog);
 	if (xdp_prog) {
@@ -1729,12 +1731,14 @@ static struct sk_buff *tun_build_skb(struct tun_struct *tun,
 		len = xdp.data_end - xdp.data;
 	}
 	rcu_read_unlock();
+	bpf_net_ctx_clear(bpf_net_ctx);
 	local_bh_enable();

 	return __tun_build_skb(tfile, alloc_frag, buf, buflen, len, pad);

 out:
 	rcu_read_unlock();
+	bpf_net_ctx_clear(bpf_net_ctx);
 	local_bh_enable();
 	return NULL;
 }
@@ -1915,20 +1919,24 @@ static ssize_t tun_get_user(struct tun_struct *tun, struct tun_file *tfile,

 	if (skb_xdp) {
 		struct bpf_prog *xdp_prog;
+		struct bpf_net_context __bpf_net_ctx, *bpf_net_ctx;
 		int ret;

 		local_bh_disable();
+		bpf_net_ctx = bpf_net_ctx_set(&__bpf_net_ctx);
 		rcu_read_lock();
 		xdp_prog = rcu_dereference(tun->xdp_prog);
 		if (xdp_prog) {
 			ret = do_xdp_generic(xdp_prog, &skb);
 			if (ret != XDP_PASS) {
 				rcu_read_unlock();
+				bpf_net_ctx_clear(bpf_net_ctx);
 				local_bh_enable();
 				goto unlock_frags;
 			}
 		}
 		rcu_read_unlock();
+		bpf_net_ctx_clear(bpf_net_ctx);
 		local_bh_enable();
 	}

@@ -2567,12 +2575,14 @@ static int tun_sendmsg(struct socket *sock, struct msghdr *m, size_t total_len)
 	if (m->msg_controllen == sizeof(struct tun_msg_ctl) &&
 	    ctl && ctl->type == TUN_MSG_PTR) {
 		struct tun_page tpage;
+		struct bpf_net_context __bpf_net_ctx, *bpf_net_ctx;
 		int n = ctl->num;
 		int flush = 0, queued = 0;

 		memset(&tpage, 0, sizeof(tpage));

 		local_bh_disable();
+		bpf_net_ctx = bpf_net_ctx_set(&__bpf_net_ctx);
 		rcu_read_lock();

 		for (i = 0; i < n; i++) {
@@ -2589,6 +2599,7 @@ static int tun_sendmsg(struct socket *sock, struct msghdr *m, size_t total_len)
 			napi_schedule(&tfile->napi);

 		rcu_read_unlock();
+		bpf_net_ctx_clear(bpf_net_ctx);
 		local_bh_enable();

 		tun_put_page(&tpage);

